  private void xrLabel28_SummaryRowChanged(object sender, EventArgs e)
        {

            if (GetCurrentColumnValue("SASIA") != null && GetCurrentColumnValue("SASIA").ToString() != "")
            {
                sasia += Convert.ToDouble(GetCurrentColumnValue("SASIA").ToString());
            }

            if (GetCurrentColumnValue("VLEFTA") != null && GetCurrentColumnValue("VLEFTA").ToString() != "")
            {
                vlefta +=  Convert.ToDouble(GetCurrentColumnValue("VLEFTA").ToString());

            }
        }
 private void xrLabel28_SummaryGetResult(object sender, SummaryGetResultEventArgs e)
        {

            if (GetCurrentColumnValue("SASIA") != null && GetCurrentColumnValue("SASIA").ToString() != "")
            {
                if (sasia != 0)
                {
                    cmim = vlefta / sasia;
                    e.Result = String.Format("{0:#.00}", cmim);
                }
            }
            e.Handled = true;
        }

        private void xrLabel28_SummaryReset(object sender, EventArgs e)
        {

            vlefta = 0;
            sasia = 0;

        }
